#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    // The original binary expects exactly two arguments: a shift amount and a string.
    // Any other usage prints a simple usage message.
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    // Validate and convert the shift argument.  The original program only accepts
    // a decimal integer optionally prefixed with '+' or '-'.  It rejects any
    // non‑numeric characters.
    char *endptr;
    long shift = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        puts("USAGE");
        return 0;
    }

    // Reduce the shift to the range 0‑25 (the behaviour of the obfuscated code).
    int s = (int)(shift % 26);
    if (s < 0) {
        s += 26;
    }

    const char *text = argv[2];
    size_t len = strlen(text);
    // The original program limits the input string to 0x400 characters.
    if (len > 0x400) {
        puts("USAGE");
        return 0;
    }

    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)text[i];
        if (c >= 'A' && c <= 'Z') {
            putchar(((c - 'A' + s) % 26) + 'A');
        } else if (c >= 'a' && c <= 'z') {
            putchar(((c - 'a' + s) % 26) + 'a');
        } else {
            putchar(c);
        }
    }
    putchar('\n');
    return 0;
}
